#ifndef INSTRUCTION_H
#define INSTRUCTION_H

#include <string>

enum class Type { R, I, S, B, U, J };
typedef unsigned int Instruction;
class Immediate {
    // 定義が確認不能とされたため、ここでは定義しない。
};
class InvalidAccess {
private:
    InvalidAccess() {}
};
class InstructionBase {
protected:
    unsigned opcode;
    unsigned rs1;
    unsigned rs2;
    unsigned rd;
    unsigned funct3;
    unsigned funct7;
    Immediate imm;
    Instruction inst;
    Type t;
public:
    static constexpr unsigned int bin_mask(int digits) {
        return (1 << digits) - 1;
    }

    static unsigned int get_digits(unsigned int n, int hi, int lo) {
        return (n >> lo) & bin_mask(hi - lo + 1);
    }

    static unsigned int expand_digit(unsigned int digit, int lo) {
        return digit ? (0xffffffff << lo) : 0;
    }

    bool is_valid(const std::string &key) {
        if (t == Type::R && key == "imm") return false;
        if (t == Type::I && (key == "rs2" || key == "funct7")) return false;
        if (t == Type::S && (key == "rd" || key == "funct7")) return false;
        if (t == Type::B && (key == "rd" || key == "funct7")) return false;
        if ((t == Type::U || t == Type::J) && (key == "rs1" || key == "rs2" || key == "funct3" || key == "funct7")) return false;
        return true;
    }

    void verify(const std::string &key) {
        if (!is_valid(key)) throw InvalidAccess();
    }

    void debug() {}

    bool has_op1() {
        return t != Type::U && t != Type::J;
    }

    bool has_op2() {
        return t == Type::R || t == Type::S || t == Type::B;
    }
};
class InstructionR : public InstructionBase {
public:
    InstructionR(const Instruction &inst) {
        opcode = get_digits(inst, 6, 0);
        rs1 = get_digits(inst, 19, 15);
        rs2 = get_digits(inst, 24, 20);
        rd = get_digits(inst, 11, 7);
        funct3 = get_digits(inst, 14, 12);
        funct7 = get_digits(inst, 31, 25);
        t = Type::R;
        this->inst = inst;
    }
};
class InstructionI : public InstructionBase {
public:
    InstructionI(const Instruction &inst) {
        opcode = get_digits(inst, 6, 0);
        rs1 = get_digits(inst, 19, 15);
        rd = get_digits(inst, 11, 7);
        funct3 = get_digits(inst, 14, 12);
        imm = Immediate(get_digits(inst, 30, 20) | expand_digit(get_digits(inst, 31, 31), 11));
        t = Type::I;
        this->inst = inst;
    }
};
class InstructionS : public InstructionBase {
public:
    InstructionS(const Instruction &inst) {
        opcode = get_digits(inst, 6, 0);
        rs1 = get_digits(inst, 19, 15);
        rs2 = get_digits(inst, 24, 20);
        funct3 = get_digits(inst, 14, 12);
        imm = Immediate((get_digits(inst, 11, 7) | (get_digits(inst, 30, 25) << 5)) | expand_digit(get_digits(inst, 31, 31), 11));
        t = Type::S;
        this->inst = inst;
    }
};
class InstructionB : public InstructionBase {
public:
    InstructionB(const Instruction &inst) {
        opcode = get_digits(inst, 6, 0);
        rs1 = get_digits(inst, 19, 15);
        rs2 = get_digits(inst, 24, 20);
        funct3 = get_digits(inst, 14, 12);
        imm = Immediate((get_digits(inst, 11, 8) << 1) | (get_digits(inst, 30, 25) << 5) | (get_digits(inst, 7, 7) << 11) | expand_digit(get_digits(inst, 31, 31), 12));
        t = Type::B;
        this->inst = inst;
    }
};
class InstructionU : public InstructionBase {
public:
    InstructionU(const Instruction &inst) {
        opcode = get_digits(inst, 6, 0);
        rd = get_digits(inst, 11, 7);
        imm = Immediate((get_digits(inst, 19, 12) << 12) | (get_digits(inst, 30, 20) << 20) | (get_digits(inst, 31, 31) << 31));
        t = Type::U;
        this->inst = inst;
    }
};
class InstructionJ : public InstructionBase {
public:
    InstructionJ(const Instruction &inst) {
        opcode = get_digits(inst, 6, 0);
        rd = get_digits(inst, 11, 7);
        imm = Immediate((get_digits(inst, 30, 21) << 1) | (get_digits(inst, 20, 20) << 11) | (get_digits(inst, 19, 12) << 12) | expand_digit(get_digits(inst, 31, 31), 20));
        t = Type::J;
        this->inst = inst;
    }
};

#endif // INSTRUCTION_H
